/** Только отображаемый русский текст. Идентификаторы, версии, числа данных
 * и архивные снимки не преобразуются. Неразрывный пробел держит число с единицей. */
export function typography(text){
 return String(text).replace(/([А-Яа-яЁё])(?=\d|v\d)/g,'$1 ')
  .replace(/(\d)(?=[А-Яа-яЁё])/g,'$1 ')
  .replace(/(\d)[ \u00a0]*(?=(?:Т|мс|МиБ|ГБ|px|%)(?:\b|[.,;:/<\s]|$))/gu,'$1\u00a0');
}
